// HasEvents applies the HasEdge predicate on the "events" edge.
func HasEvents() predicate.MysekaiBirthdaySubscription {
	return predicate.MysekaiBirthdaySubscription(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, EventsTable, EventsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasEventsWith applies the HasEdge predicate on the "events" edge with a given conditions (other predicates).
func HasEventsWith(preds ...predicate.MysekaiBirthdaySubscriptionEvent) predicate.MysekaiBirthdaySubscription {
	return predicate.MysekaiBirthdaySubscription(func(s *sql.Selector) {
		step := newEventsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MysekaiBirthdaySubscription) predicate.MysekaiBirthdaySubscription {
	return predicate.MysekaiBirthdaySubscription(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MysekaiBirthdaySubscription) predicate.MysekaiBirthdaySubscription {
	return predicate.MysekaiBirthdaySubscription(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MysekaiBirthdaySubscription) predicate.MysekaiBirthdaySubscription {
	return predicate.MysekaiBirthdaySubscription(sql.NotPredicates(p))
}
